using System.Diagnostics.CodeAnalysis;
using System.Security.Cryptography;
using System.Text;
using Curia.Domain.Search;
using Xunit;

namespace Curia.Domain.Tests.Search;

/// <summary>
/// Errata G88, R11.116, SI15: the two committed files that bind an index version to a runtime. Both are <b>regenerated by a test and compared byte for byte</b>: a runtime whose letter table or ordinal casing moved
/// turns these red, and the answer is index version 2 with the files regenerated, never an edit of the files alone. Set <c>CURIA_REGENERATE_INDEX_FILES=1</c> to write them from this runtime first.
/// </summary>
[SuppressMessage("Naming", "CA1707:Identifiers should not contain underscores", Justification = "Test names carry the requirement IDs they enforce verbatim.")]
public sealed class SearchIndexFilesTests
{
    private static bool Regenerating => Environment.GetEnvironmentVariable("CURIA_REGENERATE_INDEX_FILES") == "1";

    [Fact]
    public void R11_116_SI15_TheCommittedTagFoldTableIsWhatThisRuntimeGenerates()
    {
        var generated = SearchIndexFiles.GenerateTagFold();
        var path = SearchIndexFiles.Retrieval("tagfold-v1.tsv");
        if (Regenerating) File.WriteAllText(path, generated, new UTF8Encoding(false));

        Assert.Equal(generated, File.ReadAllText(path, Encoding.UTF8));
    }

    [Fact]
    public void R11_116_SI15_TheCommittedTagFoldTableParsesAndEveryScalarMapsToTheLeastOfItsClass()
    {
        var table = TagFoldTable.Parse(File.ReadAllText(SearchIndexFiles.Retrieval("tagfold-v1.tsv"), Encoding.UTF8));

        Assert.True(table.TryGetValue(out var fold, out var error), error?.Type);
        // OrdinalIgnoreCase is neither ToUpperInvariant nor ToLowerInvariant (errata G88, Task 0): the long s and the Kelvin sign are not folded into s and k.
        Assert.Equal("\u017F", fold!.Fold("\u017F"));
        Assert.Equal("\u212A", fold.Fold("\u212A"));
        Assert.Equal("\u00C9", fold.Fold("\u00E9"));
        Assert.Equal(fold.Fold("rust"), fold.Fold("RUST"));
        Assert.True(fold.Count > 1_000, "the table has " + fold.Count + " entries");
    }

    [Fact]
    public void R11_116_SI15_TheCommittedTokenizerPinIsWhatThisRuntimeComputes()
    {
        var computed = Convert.ToHexStringLower(TokenizerPin.Compute()) + "\n";
        var path = SearchIndexFiles.Retrieval("tokenizer-units.sha256");
        if (Regenerating) File.WriteAllText(path, computed, new UTF8Encoding(false));

        Assert.Equal(computed, File.ReadAllText(path, Encoding.UTF8));
    }

    [Fact]
    public void R11_116_TheTokenizerPinCoversEveryUtf16Unit()
    {
        // 65,536 units of three bytes each: a pin over fewer units would call a runtime unchanged that had changed a letter above them.
        var pin = TokenizerPin.Compute();
        Assert.Equal(SHA256.HashSizeInBytes, pin.Length);
    }
}
